pub enum RestBindingField {
    RestMethod,
    RestPath,
    RestQuery,
    RestHeaders,
    RestBody,
    RestTls,
    RestAuthBasic,
    RestResponseFormat,
}

pub fn rest_binding_field_key(field: RestBindingField) -> String {
    match field.clone() {
    RestBindingField::RestMethod => "method".to_string(),
    RestBindingField::RestPath => "path".to_string(),
    RestBindingField::RestQuery => "query".to_string(),
    RestBindingField::RestHeaders => "headers".to_string(),
    RestBindingField::RestBody => "body".to_string(),
    RestBindingField::RestTls => "tls".to_string(),
    RestBindingField::RestAuthBasic => "auth_basic".to_string(),
    RestBindingField::RestResponseFormat => "response_format".to_string(),
}
}

pub fn rest_binding_field_of_key(key: String) -> Option<RestBindingField> {
    if (key.clone() == "method".to_string()) {
        crate::std_optional::optional_present(RestBindingField::RestMethod)
    } else {
        if (key.clone() == "path".to_string()) {
            crate::std_optional::optional_present(RestBindingField::RestPath)
        } else {
            if (key.clone() == "query".to_string()) {
                crate::std_optional::optional_present(RestBindingField::RestQuery)
            } else {
                if (key.clone() == "headers".to_string()) {
                    crate::std_optional::optional_present(RestBindingField::RestHeaders)
                } else {
                    if (key.clone() == "body".to_string()) {
                        crate::std_optional::optional_present(RestBindingField::RestBody)
                    } else {
                        if (key.clone() == "tls".to_string()) {
                            crate::std_optional::optional_present(RestBindingField::RestTls)
                        } else {
                            if (key.clone() == "auth_basic".to_string()) {
                                crate::std_optional::optional_present(RestBindingField::RestAuthBasic)
                            } else {
                                if (key.clone() == "response_format".to_string()) {
                                    crate::std_optional::optional_present(RestBindingField::RestResponseFormat)
                                } else {
                                    crate::std_optional::optional_absent()
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

